var BAG_KEYS=Object.keys(BAG).sort(function(a,b){return b.length-a.length}),BUND_KEYS=Object.keys(BUND).sort(function(a,b){return b.length-a.length});
function bagheliText(s){BAG_KEYS.forEach(function(k){s=s.split(k).join(BAG[k])});return s}
function bundeliText(s){BUND_KEYS.forEach(function(k){s=s.split(k).join(BUND[k])});return s}
function translateBagheli(root){
 if(S.lang!=="bagheli"&&S.lang!=="bundeli")return;
 var translate=S.lang==="bundeli"?bundeliText:bagheliText;
 var walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),node;
 while((node=walker.nextNode()))if(!node.parentElement.closest("[data-user-content]"))node.nodeValue=translate(node.nodeValue);
 Array.prototype.forEach.call(root.querySelectorAll("[placeholder],[aria-label],[title]"),function(el){
  ["placeholder","aria-label","title"].forEach(function(a){if(el.hasAttribute(a))el.setAttribute(a,translate(el.getAttribute(a)))})
 })
}
function notify(message){alert(S.lang==="bagheli"?bagheliText(String(message)):S.lang==="bundeli"?bundeliText(String(message)):message)}
